static int authorized(SparkWeb *server,const Request *r){char *cookie=_strdup(r->cookie),*context=NULL;int ok=0;for(char *p=strtok_s(cookie,";",&context);p;p=strtok_s(NULL,";",&context)){while(*p==' ')p++;if(!strncmp(p,"spark343=",9)&&secure_equal(p+9,server->token))ok=1;}free(cookie);return ok;}
static int same_origin(const Request *r){char expected[1024];snprintf(expected,sizeof(expected),"http://%s",r->host);return !strcmp(r->origin,expected);}
static int decode(const char *source,size_t n,char *out,size_t capacity){size_t j=0;for(size_t i=0;i<n;i++){unsigned char ch=(unsigned char)source[i];if(ch=='%'){if(i+2>=n)return 0;char hex[3]={source[i+1],source[i+2],0},*end;long v=strtol(hex,&end,16);if(*end)return 0;ch=(unsigned char)v;i+=2;}if(ch<32||ch==127||j+1>=capacity)return 0;out[j++]=(char)ch;}out[j]=0;return MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,out,-1,NULL,0)!=0;}
