static const char *job_status(WebJob *job){return !job->complete?"running":job->ok?"done":WaitForSingleObject(job->cancel,0)==WAIT_OBJECT_0?"cancelled":"error";}
static void job_path(SparkWeb *server,const char *id,wchar_t path[32768]){wchar_t *name=wide(id);swprintf(path,32768,L"%ls\\web-job-%ls.json",server->directory,name);free(name);}
