    wchar_t *path=allocate(32768*sizeof(wchar_t));swprintf(path,32768,L"%ls\\web-job-*.json",server->directory);WIN32_FIND_DATAW info;HANDLE find=FindFirstFileW(path,&info);SpoolFile *files=allocate(8192*sizeof(*files));int count=0;
