    trim_jobs(server);WebJob *job=allocate(sizeof(*job));strcpy(job->id,id);job->server=server;job->model=_strdup(model);job->threadId=_strdup(str(saved,"threadId"));job->cancel=CreateEventW(NULL,TRUE,FALSE,NULL);job->done=job->complete=1;job->ok=!strcmp(str(saved,"status"),"done");adds(&job->stream,str(saved,"stream"));snprintf(job->error,sizeof(job->error),"%s",!strcmp(str(saved,"status"),"running")?"343 stopped before this reply finished. Recovered partial output.":str(saved,"error"));if(!strcmp(str(saved,"status"),"cancelled")||!strcmp(str(saved,"status"),"running"))SetEvent(job->cancel);job->next=server->jobs;server->jobs=job;cJSON_Delete(saved);return job;
