    cJSON *finished=host_call(client->server,model,"/generation-finished","POST",NULL,&status);cJSON_Delete(finished);
    if(!ok)failure(client->socket,502,error);else if(cJSON_IsTrue(get(body,"stream"))){adds(&job.stream,"data: [DONE]\n\n");response(client->socket,200,"text/event-stream",job.stream.p,job.stream.n,NULL);}
    else{cJSON *out=cJSON_CreateObject(),*choices=cJSON_AddArrayToObject(out,"choices"),*choice=cJSON_CreateObject(),*message=cJSON_AddObjectToObject(choice,"message");setstr(message,"role","assistant");setstr(message,"content",job.text.p?job.text.p:"");if(job.reasoning.n)setstr(message,"reasoning_content",job.reasoning.p);setstr(choice,"finish_reason","stop");cJSON_AddItemToArray(choices,choice);reply_json(client->socket,200,out);}free(job.stream.p);free(job.text.p);free(job.reasoning.p);
