    if(!strcmp(route,"/llm/tokenize")&&(!cJSON_IsString(get(body,"content"))||strlen(str(body,"content"))>SPARK_TEXT)){failure(client->socket,400,"Tokenization requires bounded text.");return;}
    int status;cJSON *config=host_call(client->server,model,"/runtime-config","GET",NULL,&status);if(!config||status!=200){if(config)reply_json(client->socket,status,config);else failure(client->socket,503,"343 is closing.");return;}
