    if(ok){char base[128];snprintf(base,sizeof(base),"http://127.0.0.1:%hu",client->server->runner.port);wchar_t *path=wide(route+4);char *json=!strcmp(r->method,"GET")?NULL:cJSON_PrintUnformatted(body);ok=http_request(base,path,json,client->server->runner.key,client->server->cancel,NULL,NULL,&result,30000,error);free(json);free(path);}cJSON_Delete(config);
